  M.services.forEach(s => { (s.log || []).forEach(h => R.push({ at: h.at, by: h.by, area: 'Service item', ref: s.code, client: '', what: h.what, href: '#svc/view/' + s.code })); (s.hist || []).forEach(h => R.push({ at: h.at, by: h.by, area: 'Standard rate', ref: s.code, client: '', what: `${sar(h.from)} → ${sar(h.to)} from ${fmtDate(h.eff)}${h.why ? ': ' + h.why : ''}`, href: '#svc/view/' + s.code })); });
